from contextlib import contextmanager

class Timer:
    def __enter__(self):
        print("enter")
        return self
    def __exit__(self, exc_type, exc, tb):
        print("exit, error:", exc_type)
        return False

with Timer() as t:
    print("working")

@contextmanager
def booking(slot):
    print("lock", slot)
    try:
        yield f"booked {slot}"
    finally:
        print("unlock", slot)

try:
    with booking("9:00") as b:
        print(b)
        raise ValueError("double booking")
except ValueError as e:
    print("caught:", e)

